<script setup lang="ts">
import { onMounted,ref } from 'vue';import type { AdminAccessView,AdminAuditView,AdminPlayerView } from '@eclipse/shared';import { rpc } from '../core/rpc';
const access=ref<AdminAccessView|null>(null),players=ref<AdminPlayerView[]>([]),audit=ref<AdminAuditView[]>([]),error=ref(''),reason=ref(''),minutes=ref('60'),busy=ref(false);const can=(p:string)=>!!access.value&&(access.value.permissions.includes('*')||access.value.permissions.includes(p));const load=async()=>{error.value='';const a=await rpc<AdminAccessView>('eclipse:admin:access');if(!a.ok){error.value='Нет доступа к админ-панели';access.value=null;return;}access.value=a.data;const [p,l]=await Promise.all([rpc<AdminPlayerView[]>('eclipse:admin:online'),can('audit.view')?rpc<AdminAuditView[]>('eclipse:admin:audit',{limit:50}):Promise.resolve(null)]);if(p.ok)players.value=p.data;if(l&&l.ok)audit.value=l.data;};const act=async(action:string,p:AdminPlayerView)=>{busy.value=true;const payload={targetPlayerId:p.playerId,reason:reason.value,minutes:Number(minutes.value)};const r=await rpc<{success:true}>(`eclipse:admin:${action}`,payload);busy.value=false;if(!r.ok)error.value=r.code;else await load();};onMounted(()=>void load());
</script>
<template><section><div class="head"><div><small>ADMIN RBAC</small><h2>{{access?`${access.role} · L${access.level}`:'Доступ закрыт'}}</h2></div><button @click="load">Обновить</button></div><p v-if="error" class="error">{{error}}</p><template v-if="access"><div class="inputs"><input v-model="reason" placeholder="Причина для kick/ban"><input v-model="minutes" type="number" min="1" max="525600" placeholder="Минуты бана"></div><h3>Игроки онлайн</h3><div class="players"><article v-for="p in players" :key="p.playerId"><div><b>#{{p.playerId}} · {{p.name}}</b><small>Static {{p.characterId}} · HP {{p.health}} · ARM {{p.armour}} · DIM {{p.dimension}}</small></div><div class="actions"><button v-if="can('players.heal')" :disabled="busy" @click="act('heal',p)">Heal</button><button v-if="can('players.teleport')" :disabled="busy" @click="act('goto',p)">Goto</button><button v-if="can('players.teleport')" :disabled="busy" @click="act('bring',p)">Bring</button><button v-if="can('players.kick')" :disabled="busy" @click="act('kick',p)">Kick</button><button v-if="can('players.ban')" :disabled="busy" class="danger" @click="act('ban',p)">Ban</button></div></article></div><template v-if="can('audit.view')"><h3>Audit log</h3><div class="audit"><article v-for="x in audit" :key="x.id"><b>{{x.action}}</b><span>{{x.targetCharacterId?`target ${x.targetCharacterId}`:'—'}} · {{new Date(x.createdAt).toLocaleString('ru-RU')}}</span><small>{{x.reason||''}}</small></article></div></template></template></section></template>
<style scoped>.head{display:flex;justify-content:space-between;align-items:center}.inputs{display:flex;gap:8px;margin:12px 0}.inputs input{flex:1;padding:9px;background:var(--e-surface-1);border:1px solid var(--e-border);color:var(--e-text-primary);border-radius:8px}.players article{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:11px;border-bottom:1px solid var(--e-border)}.players article>div:first-child,.audit article{display:flex;flex-direction:column;gap:4px}.actions{display:flex;gap:6px;flex-wrap:wrap}.audit{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.audit article{padding:10px;border:1px solid var(--e-border);border-radius:10px}.error,.danger{color:#ff8585}small,span{color:var(--e-text-muted)}button{padding:7px 10px;border:1px solid var(--e-border);border-radius:8px;background:var(--e-surface-2);color:var(--e-text-primary)}</style>